import os
from typing import Optional, Tuple

from google import genai
from google.genai import types
from PIL import Image

__CITATION__ = "[web:1]"

def get_gemini_client(
    api_key: Optional[str] = None,
    *,
    vertexai: Optional[bool] = None,
    project: Optional[str] = None,
    location: Optional[str] = None,
) -> Optional[genai.Client]:
    use_vertex_env = os.getenv("GOOGLE_GENAI_USE_VERTEXAI", "").strip().lower() in {"1", "true", "yes", "on"}
    use_vertex = use_vertex_env if vertexai is None else bool(vertexai)

    if use_vertex:
        resolved_project = (project or os.getenv("GOOGLE_CLOUD_PROJECT", "")).strip()
        resolved_location = (location or os.getenv("GOOGLE_CLOUD_LOCATION", "")).strip()
        if not resolved_project or not resolved_location:
            return None
        return genai.Client(vertexai=True, project=resolved_project, location=resolved_location)

    resolved_key = (api_key or os.getenv("GOOGLE_API_KEY") or os.getenv("GEMINI_API_KEY") or "").strip()
    if not resolved_key:
        return None
    return genai.Client(api_key=resolved_key)

def generate_image_with_gemini(prompt: str) -> Tuple[Optional[Image.Image], Optional[str]]:
    if not isinstance(prompt, str) or not prompt.strip():
        return None, "A prompt üres vagy érvénytelen"

    client = get_gemini_client()
    if client is None:
        return None, "Gemini API kulcs nincs beállítva"

    try:
        model = "gemini-3-pro-image-preview"
        contents = [
            types.Content(
                role="user",
                parts=[
                    types.Part.from_text(text=prompt),
                ],
            )
        ]
        config = types.GenerateContentConfig(
            response_modalities=["TEXT", "IMAGE"]
        )
        response = client.models.generate_content(
            model=model,
            contents=contents,
            config=config,
        )

        image_out: Optional[Image.Image] = None
        parts = getattr(response, "parts", None)
        if parts:
            for part in parts:
                inline_data = getattr(part, "inline_data", None)
                if inline_data is not None:
                    try:
                        image_out = part.as_image()
                        if image_out is not None:
                            break
                    except Exception:
                        continue

        if image_out is None:
            return None, "Nem érkezett kép a modelltől"

        return image_out, None
    except Exception as e:
        return None, f"Gemini hiba: {e}"
    finally:
        try:
            client.close()
        except Exception:
            pass
